// rust-analyzer pass (2026-10-12). Items generated by a macro invoked at
// item level — ripgrep's 663 `rgtest!(name, |dir, cmd| {...})` tests,
// bitflags!, thread_local! — have no syntax the parser can see, so they had
// no symbol and every call inside them had no caller: TestCommand.assert_err
// has 60 call sites in ripgrep's tests and grove listed none. rust-analyzer
// expands the macros and type-checks the workspace; its SCIP export names
// each generated item (with the invocation as its span) and resolves every
// reference inside it.
//
// The pass adds only what the parser cannot see: declarations outside any
// parsed function body that the parser lacks, and the calls/type uses made
// from or to those declarations. Calls between parsed declarations keep
// their existing resolution.
//
// It runs only where it can matter — some Rust file has a macro invocation
// at item level. On an incremental re-index it runs again only when an
// edited file has one or holds compiler-declared symbols; any other edit
// reuses the edits of the last run (rustScipCache) instead of paying for a
// whole-workspace analysis (tokio: ~11s) on every save.

// rustAnalyzerBin locates rust-analyzer: $GROVE_RUST_ANALYZER (a path, or
// 0/false/off to disable the pass), PATH, then ~/.cargo/bin.
func rustAnalyzerBin() (string, string) {
	if value := strings.TrimSpace(os.Getenv("GROVE_RUST_ANALYZER")); value != "" {
		if isFalse(value) {
			return "", "disabled by GROVE_RUST_ANALYZER"
		}
		return value, ""
	}
	if path, err := exec.LookPath("rust-analyzer"); err == nil {
		return path, ""
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return "", "rust-analyzer not found"
	}
	exe := "rust-analyzer"
	if runtime.GOOS == "windows" {
		exe += ".exe"
	}
	if path := filepath.Join(home, ".cargo", "bin", exe); fileExists(path) {
		return path, ""
	}
	// The VS Code extension (and its forks) ships its own server binary
	// rather than putting one on PATH; take the newest installed version.
	for _, editor := range []string{".vscode", ".vscode-insiders", ".cursor", ".windsurf"} {
		matches, _ := filepath.Glob(filepath.Join(home, editor, "extensions", "rust-lang.rust-analyzer-*", "server", exe))
		sort.Strings(matches)
		for i := len(matches) - 1; i >= 0; i-- {
			if fileExists(matches[i]) {
				return matches[i], ""
			}
		}
	}
	return "", "rust-analyzer not found (PATH, ~/.cargo/bin, editor extensions)"
}

func fileExists(path string) bool {
	info, err := os.Stat(path)
	return err == nil && !info.IsDir()
}

// rustItemMacroPattern matches a macro invocation at the start of a line:
// `name!(`, `path::name! {`, `name![`. macro_rules! definitions are excluded
// by the caller.
var rustItemMacroPattern = regexp.MustCompile(`(?m)^[ \t]*(?:[A-Za-z_][A-Za-z0-9_]*::)*([A-Za-z_][A-Za-z0-9_]*)![ \t]*[({\[]`)

// rustItemMacroFiles returns, per file, the delimiters of its macro
// invocations outside every parsed function body — the places a macro can
// generate items. "{" bodies are mostly item lists the parser reads itself
// (astkit: cfg_rt! { pub fn .. }); "(" and "[" are arguments the macro turns
// into items only rust-analyzer can see (rgtest!(r16, ..) -> fn r16).
func rustItemMacroFiles(root string, files []string, symbols []core.SymbolRecord) map[string]string {
	bodies := map[string][]core.LineRange{}
	for _, s := range symbols {
		if s.Language == "rust" && callableKind(s.Kind) {
			bodies[s.FilePath] = append(bodies[s.FilePath], s.Span)
		}
	}
	out := map[string]string{}
	for _, file := range files {
		content, err := osReadFile(filepath.Join(root, filepath.FromSlash(file)))
		if err != nil {
			continue
		}
		masked := maskCode("rust", string(content))
		for _, loc := range rustItemMacroPattern.FindAllStringSubmatchIndex(masked, -1) {
			if masked[loc[2]:loc[3]] == "macro_rules" {
				continue
			}
			line := strings.Count(masked[:loc[2]], "\n") + 1
			inBody := false
			for _, span := range bodies[file] {
				if span.Start <= line && line <= span.End {
					inBody = true
					break
				}
			}
			if delim := masked[loc[1]-1 : loc[1]]; !inBody && !strings.Contains(out[file], delim) {
				out[file] += delim
			}
		}
	}
	return out
}

// rustScipNeeded decides whether this run invokes rust-analyzer. Its call
// edges are the Rust call graph wherever it is installed, so a full pass
// always runs it; an incremental run re-runs it unless the resident worker
// can update the edited files (rust_worker.go).
func rustScipNeeded(req Request, macroFiles map[string]string, record *rustScipCacheFile) bool {
	return len(req.Files) > 0
}

func rustChangedHasMacro(changed []string, macroFiles map[string]string) bool {
	for _, file := range changed {
		if macroFiles[file] != "" {
			return true
		}
	}
	return false
}

// rustHasDeclared reports whether the index holds compiler-declared Rust
// symbols, i.e. whether a previous run's rust-analyzer edges must be kept.
func rustHasDeclared(symbols []core.SymbolRecord) bool {
	for _, s := range symbols {
		if s.Language == "rust" && slices.Contains(s.Modifiers, "compiler-declared") {
			return true
		}
	}
	return false
}

// rustCachedEdge names an edge's endpoints by file, qualified name, kind and
// line rather than by ID: IDs embed the file's blob SHA and change on every
// edit, so the endpoint in an edited file is found again by name.
type rustCachedEdge struct {
	FromFile string `json:"ff"`
	FromName string `json:"fq"`
	FromKind string `json:"fk"`
	FromLine int    `json:"fl"`
	ToFile   string `json:"tf"`
	ToName   string `json:"tq"`
	ToKind   string `json:"tk"`
	ToLine   int    `json:"tl"`
	Type     string `json:"t"`
}

type rustScipCacheFile struct {
	Version string           `json:"version"`
	Edges   []rustCachedEdge `json:"edges"`
	// Declared lists the files holding compiler-declared symbols.
	Declared []string `json:"declared"`
}

const rustScipCacheVersion = "2"

func rustScipCachePath(root string) string {
	return filepath.Join(rustAnalyzerTargetDir(root), "grove-edges.json")
}

// saveRustScipCache records the edges of a rust-analyzer run and the files
// holding compiler-declared symbols.
func saveRustScipCache(root string, symbols []core.SymbolRecord, edges []core.Edge) error {
	byID := make(map[string]*core.SymbolRecord, len(symbols))
	file := rustScipCacheFile{Version: rustScipCacheVersion}
	for i := range symbols {
		s := &symbols[i]
		byID[s.ID] = s
		if s.Language == "rust" && slices.Contains(s.Modifiers, "compiler-declared") && !slices.Contains(file.Declared, s.FilePath) {
			file.Declared = append(file.Declared, s.FilePath)
		}
	}
	sort.Strings(file.Declared)
	for _, e := range edges {
		from, to := byID[e.From], byID[e.To]
		if from == nil || to == nil {
			continue
		}
		file.Edges = append(file.Edges, rustCachedEdge{
			FromFile: from.FilePath, FromName: from.QualifiedName, FromKind: string(from.Kind), FromLine: from.Span.Start,
			ToFile: to.FilePath, ToName: to.QualifiedName, ToKind: string(to.Kind), ToLine: to.Span.Start,
			Type: string(e.Type),
		})
	}
	data, err := json.Marshal(file)
	if err != nil {
		return err
	}
	path := rustScipCachePath(root)
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	tmp := path + ".tmp"
	if err := os.WriteFile(tmp, data, 0o644); err != nil {
		return err
	}
	return os.Rename(tmp, path)
}

// readRustScipCache returns the record of the last rust-analyzer run, or nil.
func readRustScipCache(root string) *rustScipCacheFile {
	data, err := osReadFile(rustScipCachePath(root))
	if err != nil {
		return nil
	}
	var file rustScipCacheFile
	if json.Unmarshal(data, &file) != nil || file.Version != rustScipCacheVersion {
		return nil
	}
	return &file
}

// rustCachedEdges re-resolves a run's recorded edges against the current
// symbols. An endpoint that no longer exists drops its edge.
func rustCachedEdges(file *rustScipCacheFile, symbols []core.SymbolRecord) []core.Edge {
	byName := map[string][]*core.SymbolRecord{}
	for i := range symbols {
		s := &symbols[i]
		if s.Language == "rust" {
			key := s.FilePath + "\x00" + s.QualifiedName + "\x00" + string(s.Kind)
			byName[key] = append(byName[key], s)
		}
	}
	// Several symbols can share a qualified name in one file (two trait
	// impls' fmt); the one nearest the recorded line is the same declaration.
	find := func(file, name, kind string, line int) *core.SymbolRecord {
		var best *core.SymbolRecord
		for _, s := range byName[file+"\x00"+name+"\x00"+kind] {
			if best == nil || abs(s.Span.Start-line) < abs(best.Span.Start-line) {
				best = s
			}
		}
		return best
	}
	var edges []core.Edge
	for _, c := range file.Edges {
		from := find(c.FromFile, c.FromName, c.FromKind, c.FromLine)
		to := find(c.ToFile, c.ToName, c.ToKind, c.ToLine)
		if from == nil || to == nil {
			continue
		}
		edges = append(edges, symbolEdge(*from, *to, core.EdgeType(c.Type), 0.98))
	}
	return edges
}

func abs(n int) int {
	if n < 0 {
		return -n
	}
	return n
}

// runRustAnalyzerScip runs `rust-analyzer scip` over the workspace and
// returns the raw index. Build-script and proc-macro output goes to a
// grove-owned target dir, so the pass neither writes the user's target/ nor
// waits on the lock of their running cargo build.
func runRustAnalyzerScip(ctx context.Context, bin, root string) ([]byte, error) {
	tmp, err := os.MkdirTemp("", "grove-rust-scip-*")
	if err != nil {
		return nil, err
	}
	defer os.RemoveAll(tmp)
	out := filepath.Join(tmp, "index.scip")
	cmd := exec.CommandContext(ctx, bin, "scip", root, "--output", out)
	cmd.Dir = root
	cmd.Env = append(os.Environ(), "CARGO_TARGET_DIR="+rustAnalyzerTargetDir(root))
	if log, err := cmd.CombinedOutput(); err != nil {
		return nil, fmt.Errorf("%w: %s", err, lastLine(string(log)))
	}
	return os.ReadFile(out)
}

func rustAnalyzerTargetDir(root string) string {
	sum := sha256.Sum256([]byte(root))
	base, err := os.UserCacheDir()
	if err != nil {
		base = os.TempDir()
	}
	return filepath.Join(base, "grove", "rust-analyzer", hex.EncodeToString(sum[:8]))
}

func lastLine(text string) string {
	text = strings.TrimSpace(text)
	if i := strings.LastIndexByte(text, '\n'); i >= 0 {
		text = text[i+1:]
	}
	return text
}

// SCIP protocol numbers (scip.proto): the fields and kinds this pass reads.
const (
	scipIndexDocuments     = 2
	scipDocPath            = 1
	scipDocOccurrences     = 2
	scipDocSymbols         = 3
	scipOccRange           = 1
	scipOccSymbol          = 2
	scipOccRoles           = 3
	scipOccEnclosingRange  = 7
	scipInfoSymbol         = 1
	scipInfoKind           = 5
	scipRoleDefinition     = 1
	scipKindConstant       = 8
	scipKindConstructor    = 9
	scipKindEnum           = 11
	scipKindField          = 15
	scipKindFunction       = 17
	scipKindMethod         = 26
	scipKindStruct         = 49
	scipKindTrait          = 53
	scipKindTypeAlias      = 55
	scipKindUnion          = 59
	scipKindTraitMethod    = 70
	scipKindStaticMethod   = 80
	scipKindStaticVariable = 82
)

type scipOccurrence struct {
	Line, Col, EndLine, EndCol int // 0-based, as SCIP encodes them
	Symbol                     string
	Definition                 bool
	Enclosing                  [2]int // 0-based start/end line; Enclosing[1] < 0 when absent
}

type scipDocument struct {
	Path        string
	Occurrences []scipOccurrence
	Kinds       map[string]int
}

// decodeScip reads the documents of a SCIP index: path, occurrences and
// the kinds of the symbols each document defines.
func decodeScip(raw []byte) ([]scipDocument, error) {
	var docs []scipDocument
	err := scipFields(raw, func(num protowire.Number, typ protowire.Type, value []byte, _ uint64) error {
		if num != scipIndexDocuments || typ != protowire.BytesType {
			return nil
		}
		doc := scipDocument{Kinds: map[string]int{}}
		err := scipFields(value, func(num protowire.Number, typ protowire.Type, value []byte, _ uint64) error {
			switch {
			case num == scipDocPath && typ == protowire.BytesType:
				doc.Path = filepath.ToSlash(string(value))
			case num == scipDocOccurrences && typ == protowire.BytesType:
				occ, err := decodeScipOccurrence(value)
				if err != nil {
					return err
				}
				doc.Occurrences = append(doc.Occurrences, occ)
			case num == scipDocSymbols && typ == protowire.BytesType:
				var symbol string
				var kind int
				err := scipFields(value, func(num protowire.Number, typ protowire.Type, value []byte, v uint64) error {
					switch {
					case num == scipInfoSymbol && typ == protowire.BytesType:
						symbol = string(value)
					case num == scipInfoKind && typ == protowire.VarintType:
						kind = int(v)
					}
					return nil
				})
				if err != nil {
					return err
				}
				doc.Kinds[symbol] = kind
			}
			return nil
		})
		if err != nil {
			return err
		}
		docs = append(docs, doc)
		return nil
	})
	return docs, err
}

func decodeScipOccurrence(raw []byte) (scipOccurrence, error) {
	occ := scipOccurrence{Enclosing: [2]int{-1, -1}}
	var rng, enclosing []int
	err := scipFields(raw, func(num protowire.Number, typ protowire.Type, value []byte, v uint64) error {
		switch num {
		case scipOccRange, scipOccEnclosingRange:
			ints, err := scipPackedInts(typ, value, v)
			if err != nil {
				return err
			}
			if num == scipOccRange {
				rng = append(rng, ints...)
			} else {
				enclosing = append(enclosing, ints...)
			}
		case scipOccSymbol:
			if typ == protowire.BytesType {
				occ.Symbol = string(value)
			}
		case scipOccRoles:
			if typ == protowire.VarintType {
				occ.Definition = int32(v)&scipRoleDefinition != 0
			}
		}
		return nil
	})
	if err != nil {
		return occ, err
	}
	// [startLine, startChar, endLine, endChar], or three values when the
	// range is on one line.
	switch len(rng) {
	case 3:
		occ.Line, occ.Col, occ.EndLine, occ.EndCol = rng[0], rng[1], rng[0], rng[2]
	case 4:
		occ.Line, occ.Col, occ.EndLine, occ.EndCol = rng[0], rng[1], rng[2], rng[3]
	default:
		return occ, fmt.Errorf("scip: occurrence range has %d values", len(rng))
	}
	switch len(enclosing) {
	case 3:
		occ.Enclosing = [2]int{enclosing[0], enclosing[0]}
	case 4:
		occ.Enclosing = [2]int{enclosing[0], enclosing[2]}
	}
	return occ, nil
}

// scipPackedInts reads a repeated int32 field in packed or unpacked form.
func scipPackedInts(typ protowire.Type, value []byte, v uint64) ([]int, error) {
	if typ == protowire.VarintType {
		return []int{int(int32(v))}, nil
	}
	if typ != protowire.BytesType {
		return nil, nil
	}
	var out []int
	for len(value) > 0 {
		n, size := protowire.ConsumeVarint(value)
		if size < 0 {
			return nil, protowire.ParseError(size)
		}
		out = append(out, int(int32(n)))
		value = value[size:]
	}
	return out, nil
}

// scipFields walks one message's fields. value is set for length-delimited
// fields, v for varints.
func scipFields(raw []byte, visit func(num protowire.Number, typ protowire.Type, value []byte, v uint64) error) error {
	for len(raw) > 0 {
		num, typ, size := protowire.ConsumeTag(raw)
		if size < 0 {
			return protowire.ParseError(size)
		}
		raw = raw[size:]
		var value []byte
		var v uint64
		switch typ {
		case protowire.VarintType:
			v, size = protowire.ConsumeVarint(raw)
		case protowire.BytesType:
			value, size = protowire.ConsumeBytes(raw)
		default:
			size = protowire.ConsumeFieldValue(num, typ, raw)
		}
		if size < 0 {
			return protowire.ParseError(size)
		}
		raw = raw[size:]
		if err := visit(num, typ, value, v); err != nil {
			return err
		}
	}
	return nil
}

// rustScipDeclKind maps a SCIP kind to the compilerDecl kind of a Rust
// declaration the graph can use; "" skips it (modules, macros, enum
// variants, associated types).
func rustScipDeclKind(kind int, parent string) string {
	switch kind {
	case scipKindFunction:
		if parent != "" {
			return "method"
		}
		return "function"
	case scipKindMethod, scipKindStaticMethod, scipKindTraitMethod, scipKindConstructor:
		return "method"
	case scipKindStruct, scipKindUnion:
		return "struct"
	case scipKindEnum:
		return "enum"
	case scipKindTrait:
		return "trait"
	case scipKindTypeAlias:
		return "type"
	case scipKindField:
		return "field"
	case scipKindConstant:
		return "const"
	case scipKindStaticVariable:
		return "variable"
	}
	return ""
}

// rustScipParent names the type a SCIP symbol belongs to, the parser's
// ParentSymbol convention: `impl#[TestCommand]assert_err().` and
// `TestCommand#assert_err().` both give TestCommand; a free function gives "".
func rustScipParent(symbol string) string {
	parts := strings.SplitN(symbol, " ", 5)
	if len(parts) < 5 {
		return ""
	}
	desc := parts[4]
	// Drop the last descriptor: the declaration itself.
	desc = strings.TrimSuffix(desc, ".")
	desc = strings.TrimSuffix(desc, "/")
	desc = strings.TrimSuffix(desc, "#")
	if strings.HasSuffix(desc, ")") {
		if i := strings.LastIndexByte(desc, '('); i >= 0 {
			desc = desc[:i]
		}
	}
	end := len(desc)
	for end > 0 && isRustIdentByte(desc[end-1]) {
		end--
	}
	desc = desc[:end]
	if i := strings.LastIndex(desc, "impl#["); i >= 0 {
		rest := desc[i+len("impl#["):]
		if j := strings.IndexByte(rest, ']'); j >= 0 {
			return rest[:j]
		}
	}
	if !strings.HasSuffix(desc, "#") {
		return ""
	}
	desc = strings.TrimSuffix(desc, "#")
	start := len(desc)
	for start > 0 && isRustIdentByte(desc[start-1]) {
		start--
	}
	return desc[start:]
}

// rustScipPass turns a decoded index into compiler-declared symbols and the
// edges made from them.
// isolatedRoots are the root files of test, bench and example targets:
// separate crates nothing else in the repository can call into.
func rustScipPass(req Request, docs []scipDocument, isolatedRoots map[string]bool) ([]core.SymbolRecord, []core.Edge) {
	inScope := fileSet(req.Files)
	bodies := map[string][]core.SymbolRecord{}
	enums := map[string][]core.SymbolRecord{}
	for _, s := range req.Symbols {
		if s.Language != "rust" || slices.Contains(s.Modifiers, "compiler-declared") {
			continue
		}
		if callableKind(s.Kind) {
			bodies[s.FilePath] = append(bodies[s.FilePath], s)
		}
		if s.Kind == core.KindEnum {
			enums[s.FilePath] = append(enums[s.FilePath], s)
		}
	}
	// The parser indexes enum variants but not a struct-like variant's
	// fields (astkit, 2026-09-26); declaring them only when rust-analyzer
	// is installed would make the graph depend on the machine.
	inParsedEnum := func(file string, line int) bool {
		for _, s := range enums[file] {
			if s.Span.Start <= line && line <= s.Span.End {
				return true
			}
		}
		return false
	}
	inParsedBody := func(file string, line int) bool {
		for _, s := range bodies[file] {
			if s.Span.Start <= line && line <= s.Span.End {
				return true
			}
		}
		return false
	}
	lines := map[string][]string{}
	sourceLine := func(file string, line int) string {
		src, ok := lines[file]
		if !ok {
			if data, err := osReadFile(filepath.Join(req.Root, filepath.FromSlash(file))); err == nil {
				src = strings.Split(string(data), "\n")
			}
			lines[file] = src
		}
		if line < 0 || line >= len(src) {
			return ""
		}
		return src[line]
	}
	occName := func(file string, o scipOccurrence) string {
		text := sourceLine(file, o.Line)
		if o.EndLine != o.Line || o.Col < 0 || o.EndCol > len(text) || o.Col >= o.EndCol {
			return ""
		}
		return strings.TrimPrefix(text[o.Col:o.EndCol], "r#")
	}

	var decls []compilerDecl
	for _, doc := range docs {
		if !inScope[doc.Path] {
			continue
		}
		for _, o := range doc.Occurrences {
			if !o.Definition || strings.HasPrefix(o.Symbol, "local ") {
				continue
			}
			parent := rustScipParent(o.Symbol)
			kind := rustScipDeclKind(doc.Kinds[o.Symbol], parent)
			name := occName(doc.Path, o)
			if kind == "" || name == "" || inParsedBody(doc.Path, o.Line+1) || inParsedEnum(doc.Path, o.Line+1) {
				continue
			}
			start, end := o.Line+1, o.EndLine+1
			if o.Enclosing[1] >= 0 {
				start, end = o.Enclosing[0]+1, o.Enclosing[1]+1
			}
			qualified := name
			if parent != "" {
				qualified = parent + "." + name
			}
			decls = append(decls, compilerDecl{File: doc.Path, Kind: kind, Name: name, Qualified: qualified, Parent: parent, Start: start, End: end})
		}
	}
	declared := compilerDeclaredSymbolsFor(req, "rust", decls)

	// Every in-repo definition resolves to the innermost symbol (parsed,
	// stored or just declared) of that name whose span holds it.
	all := make([]core.SymbolRecord, 0, len(req.Symbols)+len(declared))
	for _, s := range req.Symbols {
		if s.Language == "rust" {
			all = append(all, s)
		}
	}
	all = append(all, declared...)
	byFileName := map[string][]int{}
	callers := map[string][]int{}
	isDeclared := make([]bool, len(all))
	for i, s := range all {
		byFileName[s.FilePath+"\x00"+s.Name] = append(byFileName[s.FilePath+"\x00"+s.Name], i)
		if callableKind(s.Kind) || typeKind(s.Kind) {
			callers[s.FilePath] = append(callers[s.FilePath], i)
		}
		isDeclared[i] = slices.Contains(s.Modifiers, "compiler-declared")
	}
	innermost := func(candidates []int, line int) int {
		best := -1
		for _, i := range candidates {
			span := all[i].Span
			if span.Start <= line && line <= span.End &&
				(best < 0 || span.End-span.Start < all[best].Span.End-all[best].Span.Start) {
				best = i
			}
		}
		return best
	}
	// SCIP names a symbol by package and module path, so every integration
	// test's (or bench's, example's) root-level helper `fn rt()` gets one
	// symbol: rust-analyzer's own index cannot tell them apart. A reference
	// resolves to a definition in its own file first, never to another such
	// root (a separate crate it cannot reach), else to the only candidate.
	targets := map[string][]int{}
	for _, doc := range docs {
		for _, o := range doc.Occurrences {
			if !o.Definition || strings.HasPrefix(o.Symbol, "local ") {
				continue
			}
			if i := innermost(byFileName[doc.Path+"\x00"+occName(doc.Path, o)], o.Line+1); i >= 0 && !slices.Contains(targets[o.Symbol], i) {
				targets[o.Symbol] = append(targets[o.Symbol], i)
			}
		}
	}
	resolveTarget := func(symbol, fromFile string) (int, bool) {
		cands := targets[symbol]
		if len(cands) == 1 {
			return cands[0], true
		}
		var reachable []int
		for _, i := range cands {
			file := all[i].FilePath
			if file == fromFile {
				return i, true
			}
			if !isolatedRoots[file] {
				reachable = append(reachable, i)
			}
		}
		if len(reachable) == 1 {
			return reachable[0], true
		}
		return -1, false
	}

	var edges []core.Edge
	seen := map[string]bool{}
	for _, doc := range docs {
		if len(callers[doc.Path]) == 0 {
			continue
		}
		for _, o := range doc.Occurrences {
			if o.Definition || strings.HasPrefix(o.Symbol, "local ") {
				continue
			}
			to, ok := resolveTarget(o.Symbol, doc.Path)
			if !ok {
				continue
			}
			// Every resolved reference to a function is a call edge from the
			// innermost declaration holding it (calls, method calls through
			// inference, and functions passed as values — the same "may
			// affect" altitude as the go/types and javac passes); the graph
			// treats these as authoritative for .rs callers
			// (graph.compilerResolvedNode). Type uses stay the parser's
			// except where a compiler-declared symbol is involved (no
			// name-guessed edge may land on one,
			// graph.dropGuessesIntoCompilerDeclared).
			// Only a reference that names its target in the source counts:
			// SCIP also records implicit ones (.await -> Future::poll,
			// operators, ? -> From::from) that no identifier names, and the
			// resident server (rust_worker.go) resolves identifiers.
			from := innermost(callers[doc.Path], o.Line+1)
			if from < 0 || from == to || occName(doc.Path, o) != all[to].Name {
				continue
			}
			var edgeType core.EdgeType
			switch {
			case callableKind(all[to].Kind) && (callableKind(all[from].Kind) || isDeclared[from]):
				edgeType = core.EdgeCalls
			case typeKind(all[to].Kind) && (isDeclared[from] || isDeclared[to]):
				edgeType = core.EdgeUsesType
			default:
				continue
			}
			key := all[from].ID + "\x00" + string(edgeType) + "\x00" + all[to].ID
			if seen[key] {
				continue
			}
			seen[key] = true
			edges = append(edges, symbolEdge(all[from], all[to], edgeType, 0.98))
		}
	}
	return declared, edges
}
